/* TrialMonitorMapper.selectTrialTeacherAccounts */ SELECT pu.name AS name , pu.email AS email , pu.public_user_id AS publicUserId , pu.created_at AS createdAt , u.user_no AS userNo , u.status AS userStatus FROM superteacher_core.platform_user pu LEFT JOIN superplatform_meta.`user` u ON u.sp_user_id = pu.public_user_id WHERE pu.user_type = 'TEACHER' AND pu.created_at >= #{signupFrom} AND ( pu.name IN
#{nm}
OR pu.email IN
#{em}
) ORDER BY pu.name, pu.created_at
